class Solution {
    // 核心思路：栈加映射表做括号匹配，右括号与栈顶左括号匹配则弹出。
    // 易错点：栈空遇右括号直接返回 false，最后要求栈为空。
    // 时间复杂度 O(n)，空间复杂度 O(n)。
public:
    bool isValid(string s) {
        stack<char> st;
        unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
        for (char ch : s) {
            if (pairs.count(ch)) {
                if (st.empty() || st.top() != pairs[ch]) return false;
                st.pop();
            } else {
                st.push(ch);
            }
        }
        return st.empty();
    }
};

