def search(nums, target):
    # 核心思路：旋转数组二分，每次循环左右两半中至少有一半严格有序，
    # 先判断 target 是否落在有序半边内，再决定收缩方向。
    # 易错点：判定左半有序用 nums[lo] <= nums[mid]；找不到时返回 -1。
    # 时间复杂度 O(log n)，空间复杂度 O(1)。
    # 每次二分都有一半是有序的，先判断 target 是否落在有序半边
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:  # 左半有序
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:  # 右半有序
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

