def searchRange(nums, target):
    # 核心思路：两次二分分别求下界与上界：下界是第一个 >= target 的位置，
    # 上界是第一个 > target 的位置，答案区间为 [下界, 上界-1]。
    # 易错点：下界越界或指向的元素不等于 target 时说明不存在，返回 [-1, -1]。
    # 时间复杂度 O(log n)，空间复杂度 O(1)。
    def lower():
        # 第一个 >= target 的位置
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper():
        # 第一个 > target 的位置
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    l = lower()
    if l == len(nums) or nums[l] != target:
        return [-1, -1]
    return [l, upper() - 1]

