class MinStack:
    # 核心思路：辅助栈 min_st 同步维护当前栈内最小值。
    # 关键点：push 时仅当新值不大于 min_st 栈顶才入辅助栈；
    # pop 时若弹出值等于 min_st 栈顶则同步弹出。
    # 易错点：getMin 直接返回 min_st 栈顶即可。
    # 时间复杂度 O(1)，空间复杂度 O(n)。
    def __init__(self):
        self.st = []
        self.min_st = []

    def push(self, val: int) -> None:
        self.st.append(val)
        if not self.min_st or val <= self.min_st[-1]:
            self.min_st.append(val)

    def pop(self) -> None:
        if self.st:
            v = self.st.pop()
            if v == self.min_st[-1]:
                self.min_st.pop()

    def top(self) -> int:
        return self.st[-1]

    def getMin(self) -> int:
        return self.min_st[-1]

