        if op == 'push':
            x = int(next(it))
            st.append(x)
            if not min_st or x <= min_st[-1]:
                min_st.append(x)
        elif op == 'pop':
            if st:
                v = st.pop()
                if v == min_st[-1]:
                    min_st.pop()
        elif op == 'top':
