class MinStack {
    // 核心思路：辅助栈 min_st 与主栈同步维护当前最小值。
    // 关键点：push 时仅当 val 不大于 min_st 栈顶才入辅助栈；
    // pop 时若栈顶等于 min_st 栈顶则同步弹出。
    // 易错点：getMin 直接返回 min_st 栈顶。
    // 时间复杂度 O(1)，空间复杂度 O(n)。
public:
    stack<int> st, min_st;
    MinStack() {}

    void push(int val) {
        st.push(val);
        if (min_st.empty() || val <= min_st.top()) min_st.push(val);
    }

    void pop() {
        if (st.empty()) return;
        if (st.top() == min_st.top()) min_st.pop();
        st.pop();
    }

    int top() {
        return st.top();
    }

    int getMin() {
        return min_st.top();
    }
};

